sys_script_fix.script:
var tradeID1 = 'AU-HSBC-R';
var tradeID2 = 98768;
var tradeID3 = '-00-0';
var tradeID4 = 99876;
var market = 'dcb8b97e975e2e90a78db62de053afa1'; // from x_938076_now_utils_trade_markets_list table



for (var i = 0; i < 20; i++) {
    var tradeID = tradeID1 + "-" + (tradeID2 + (10 + i)).toString() + tradeID3 + (tradeID4 + (300 + i) ).toString();
	var reference = 'R-'+(tradeID2 + (10 + i)).toString() + tradeID3;

    //gs.info('tradeID ' + tradeID);
	   // gs.info('reference ' + reference);

    var gr = new GlideRecord("x_938076_now_utils_custody_trades");
    gr.initialize();
    gr.trade_id = tradeID;
	gr.owning_business = market;
	gr.transaction_reference = reference;
	gr.insert();
}
